1	/**
2	 * Requirement:
3	 * Processes ranked choice voting (RCV) results, redistributing votes each round,
4	 * eliminating the candidate with the fewest first-place votes, and logging each stage.
5	 * Handles tie-breaking using second-choice and least last-place votes, and logs all actions to the processing sheet.
6	 *
7	 * @returns {Array<Object>} An array of the top vote-getting candidate(s) after all calculated tie-breakers.
8	 * If there is more than one value, a tie could not be broken using second-choice and least-favorite votes.
9	*/
10	var processingSheet = null;
11	
12	/**
13	 * Core RCV algorithm, run against ballot-driven data sourced by webAdmin.js
14	 * from a Ballot-<name> sheet's own Responses section.
15	 *
16	 * @param {Array<string>} candidateNames
17	 * @param {Array<{voterName:string, ranks:Array, weight:number}>} allBallots
18	 *   ranks[i] corresponds to candidateNames[i]; weight defaults to 1 and lets
19	 *   one ballot count for more than one vote (e.g. a ballot response with an
20	 *   admin-assigned weight).
21	 * @param {Sheet=} sheet optional sheet to log elimination rounds to.
22	 * @returns {{winner:?string, tie:?Array<string>, summary:Array<Array>}}
23	 */
24	function runRankedChoiceVoting(candidateNames, allBallots, sheet) {
25	  processingSheet = sheet || null;
26	
27	  // Compress the rankings for each response
28	  allBallots = allBallots.map(({ voterName, ranks, weight }) => {
29	    // Remove blanks, sort, and reassign compressed ranks
30	    let ranked = [];
31	    for (let i = 0; i < ranks.length; i++) {
32	      if (ranks[i] !== "") {
33	        ranked.push({ idx: i, rank: parseInt(ranks[i], 10) });
34	      }
35	    }
36	    ranked.sort((a, b) => a.rank - b.rank);
37	    let compressedRanks = Array(ranks.length).fill("");
38	    ranked.forEach((entry, i) => {
39	      compressedRanks[entry.idx] = i + 1;
40	    });
41	    return { voterName, ranks: compressedRanks, weight: weight || 1 };
42	  });
43	
44	  // ranks are now compressed, e.g. [1, 2, 3, "", 5] becomes [1, 2, 3, "", 4]
45	  // with positions of candidates preserved, but ranks compressed
46	
47	  // Initialize candidate status
48	  // allCandidates is an array of objects, each object has the following properties:
49	  // index: the index of the candidate in the candidates array is the index in the ranked array
50	  var allCandidates = candidateNames.map((name) => ({
51	    name,
52	    votes: 0,
53	    eliminated: false,
54	    reason: null,
55	  }));
56	
57	  var roundNumber = 1;
58	
59	  /*
60	   * For each voter's ballot:
61	   *   - Collect their ranked choices (ignoring blanks).
62	   *   - Sort the choices by rank (so 1st choice comes first).
63	   *   - Find the highest-ranked candidate on their ballot who is still in the race (not eliminated).
64	   *   - Give that candidate one vote.
65	   *   - Stop after the first valid (non-eliminated) candidate is found.
66	   */
67	  function countVotes(ballots) {
68	    allCandidates.forEach((r) => (r.votes = 0)); // set votes to 0 for each candidate
69	
70	    ballots.forEach((ballot) => {
71	      var ranked = [];
72	      // Collect ranks and their corresponding candidate status, ranks is ordered by candidate index
73	      for (var c_i = 0; c_i < ballot.ranks.length; c_i++) {
74	        var rank = ballot.ranks[c_i];
75	        if (!isNaN(rank)) {
76	          ranked.push({ candidate: allCandidates[c_i], rank });
77	        }
78	      }
79	      ranked.sort((a, b) => a.rank - b.rank);
80	      for (var j = 0; j < ranked.length; j++) {
81	        var r = ranked[j].candidate;
82	        if (r && !r.eliminated) {
83	          r.votes += ballot.weight || 1;
84	          break;
85	        }
86	      }
87	    });
88	  }
89	  /**
90	   * Returns a table (array of arrays) summarizing candidate status.
91	   * Columns: Candidate, Status, Votes, Elimination Round, Elimination Reason
92	   * @param {Array<Object>} allCandidates - Array of candidate status objects.
93	   * @returns {Array<Array>} Table with header and one row per candidate.
94	   */
95	  function getCandidateSummaryTable(allCandidates, allBallots) {
96	
97	    const table = [
98	      [
99	        "Candidate",
100	        "Status",
101	        "Votes",
102	        "Elimination Round",
103	        "Elimination Reason",
104	      ],
105	    ];
106	    // Sort: active first by votes desc, then eliminated by round asc
107	    const sorted = allCandidates.slice().sort((a, b) => {
108	      if (a.eliminated && b.eliminated) {
109	        return b.eliminated.round - a.eliminated.round;
110	      }
111	      if (a.eliminated) return 1;
112	      if (b.eliminated) return -1;
113	      return b.votes - a.votes;
114	    });
115	    sorted.forEach((c) => {
116	      let status;
117	      if (c.eliminated) {
118	        status = "Eliminated";
119	      } else if (c.votes > (_sumBallotWeights(allBallots) / 2)) {
120	        status = "Winner";
121	      } else if (c.votes === 0) {
122	        status = "No Votes";
123	      } else {
124	        status = "Active";
125	      }
126	      table.push([
127	        c.name,
128	        status,
129	        c.eliminated ? c.eliminated.votes : c.votes,
130	        c.eliminated ? c.eliminated.round : "",
131	        c.eliminated ? c.eliminated.reason : "",
132	      ]);
133	    });
134	    return table;
135	  }
136	
137	  function getEffectiveBallots() {
138	    return allBallots.map((response) => {
139	      var ranked = [];
140	      for (var i = 0; i < response.ranks.length; i++) {
141	        var rank = response.ranks[i];
142	        if (!isNaN(rank)) {
143	          ranked.push({ candidate: allCandidates[i], rank });
144	        }
145	      }
146	      ranked = ranked
147	        .sort((a, b) => a.rank - b.rank)
148	        .filter((entry) => !entry.candidate.eliminated);
149	
150	      return ranked.map((entry, index) => ({
151	        name: entry.candidate.name,
152	        newRank: index + 1,
153	      }));
154	    });
155	  }
156	
157	  function logBallots(title, ballotData) {
158	    logProcess(["", title]);
159	    var activeCandidates = allCandidates
160	      .filter((r) => !r.eliminated)
161	      .map((r) => r.name);
162	
163	    var header = ["Voter"].concat(activeCandidates);
164	    logProcess(header);
165	
166	    ballotData.forEach((voterData, idx) => {
167	      var row = [`Voter ${idx + 1}`];
168	      activeCandidates.forEach((cand) => {
169	        var found = voterData.find((v) => v.name === cand);
170	        row.push(found ? found.newRank : "");
171	      });
172	      logProcess(row);
173	    });
174	  }
175	
176	  function logProgress(roundNumber, candidate) {
177	    var explanation = candidate.eliminated
178	      ? `Eliminated - ${candidate.eliminated.reason}, votes are redistributed`
179	      : `Wins with more than 50% of the votes`;
180	
181	    logProcess([roundNumber, candidate.name, explanation]);
182	  }
183	
184	  var eliminated = null;
185	  while (true) {
186	    logBallots(
187	      roundNumber === 1
188	        ? "Initial ballots"
189	        : `Redistributed ballots in round ${roundNumber}`,
190	      getEffectiveBallots()
191	    );
192	
193	    countVotes(allBallots);
194	  
195	    // Log the candidate summary table to the processing sheet
196	    logProcess(["", "Candidate Summary"]);
197	    getCandidateSummaryTable( allCandidates, allBallots ).forEach((row) => {
198	      logProcess(row);
199	    });
200	
201	    // Count only non-exhausted ballots
202	    var activeBallots = allBallots.filter((ballot) => {
203	      // At least one ranked candidate is not eliminated
204	      return ballot.ranks.some(
205	        (rank, i) => !isNaN(rank) && !allCandidates[i].eliminated
206	      );
207	    });
208	    var totalVotes = _sumBallotWeights(activeBallots);
209	    var winner = allCandidates.find(
210	      (r) => !r.eliminated && r.votes > totalVotes / 2
211	    );
212	
213	    if (winner) {
214	      logProgress(roundNumber, winner);
215	      Logger.log(`Winner: ${winner.name}`);
216	      return {
217	        winner: winner.name,
218	        tie: null,
219	        summary: getCandidateSummaryTable(allCandidates, allBallots),
220	      };
221	     }
222	
223	    var remaining = allCandidates.filter((r) => !r.eliminated);
224	    var minVotes = Math.min(...remaining.map((r) => r.votes));
225	    var toEliminate = remaining.filter((r) => r.votes === minVotes);
226	
227	    if (toEliminate.length === 1) {
228	      // Only one candidate has the fewest votes, eliminate them
229	      eliminated = toEliminate[0];
230	      eliminated.eliminated = {
231	        round: roundNumber,
232	        reason: "fewest votes",
233	        votes: minVotes,
234	      };
235	      logProgress(roundNumber, eliminated);
236	      roundNumber++;
237	      continue;
238	    }
239	    // More than one candidate has the fewest votes, we have a tie
240	    // eliminate one of the candidates with the fewest first place votes (standard in RCV)
241	    var { eliminate, reason } = breakTie(
242	      toEliminate,
243	      allBallots,
244	      allCandidates
245	    );
246	
247	    if (!eliminate) {
248	      // Announce tie and stop processing - tieNames is an array of names
249	      var tieNames = toEliminate.map((c) => c.name);
250	      logProcess([
251	        "",
252	        "",
253	        `Tie remains after all tie-breakers: ${tieNames.join(
254	          ", "
255	        )}. Manual review required for runoff.`,
256	      ]);
257	      return {
258	        winner: null,
259	        tie: tieNames,
260	        summary: getCandidateSummaryTable(allCandidates, allBallots),
261	      };
262	     }
263	
264	    eliminate.eliminated = {
265	      round: roundNumber,
266	      reason: reason,
267	      votes: minVotes,
268	    };
269	    logProgress(roundNumber, eliminate, getEffectiveBallots());
270	    roundNumber++;
271	  }
272	}
273	
274	/**
275	 * Attempts to break a tie among candidates with the fewest votes using a series of tie-breaking strategies:
276	 * 1. Second choice: Eliminates the candidate with the fewest second-choice votes among tied candidates.
277	 * 2. Least last-place: If still tied, eliminates the candidate with the fewest last-place votes among tied candidates.
278	 * 3. If still unresolved, reports the tie for manual resolution.
279	 * 
280	 * Logs the tie-breaking process and results to the processing sheet if provided.
281	 * 
282	 * @param {Array<Object>} candidates - Array of candidate status objects currently tied for elimination.
283	 * @param {Array<Object>} ballots - Array of deduplicated and compressed voter responses.
284	 * @param {Array<Object>} allCandidates - Array of all candidate status objects.
285	 * @returns {Object|null} The candidate object to eliminate, or null if the tie could not be resolved.
286	 */
287	function breakTie(candidates, ballots, allCandidates) {
288	  let tieMsg = "";
289	  let tiedCandidates = candidates.slice();
290	
291	  let leastSecondElim = countTieWinners(
292	    tiedCandidates,
293	    "leastSecond",
294	    ballots,
295	    allCandidates
296	  );
297	  if (leastSecondElim.length === 1) {
298	    return { eliminate: leastSecondElim[0], reason: "fewest second choice votes" };
299	  } else {
300	    // not broken by second choice, logprocess the leastSecondwinners
301	    tieMsg = "Second choice failed, tie remains: " + leastSecondElim.map((c) => c.name).join(", ");
302	    logProcess3("", "", tieMsg);
303	    tiedCandidates = leastSecondElim;
304	  }
305	
306	  let mostLastElim = countTieWinners(
307	    tiedCandidates,
308	    "mostLastPlace",
309	    ballots,
310	    allCandidates
311	  );
312	  if (mostLastElim.length === 1) {
313	    return { eliminate: mostLastElim[0], reason: "most last-place votes" };
314	  } else {
315	    // not broken by least last place, logprocess the mostLastPlacecount
316	    tieMsg = "Most last place failed, tie remains: " +  mostLastElim.map((c) => c.name).join(", ");
317	    logProcess3("", "", tieMsg);
318	    tiedCandidates = mostLastElim;
319	  }
320	
321	  // 3. Still tied: report tie for manual resolution
322	  logProcess3("", "", "Manual review required");
323	  return { eliminate: null, reason: "unable to eliminate a last place tie between: " + tiedCandidates.map((c) => c.name).join(", ")};
324	}
325	/**
326	 * Determines which candidates remain tied after applying a tie-breaker criterion.
327	 * Depending on the mode, it counts either second-choice or last-place votes for each tied candidate,
328	 * and returns the subset of candidates who have the maximum (for second choice) or minimum (for least last place) count.
329	 *
330	 * @param {Array<Object>} candidates - Array of candidate status objects currently tied.
331	 * @param {string} mode - The tie-breaking mode: "leastSecond" or "mostLastPlace".
332	 * @param {Array<Object>} ballots - Array of all deduplicated and compressed voter ballots.
333	 * @param {Array<Object>} allCandidates - Array of all candidate status objects.
334	 * @returns {Array<Object>} Array of candidate objects who remain tied after applying the tie-breaker.
335	 */
336	// Helper to count which candidates are still tied after a tie-breaker
337	function countTieWinners(candidates, mode, ballots, allCandidates) {
338	  function countByRank(rankPosition) {
339	    // rankPosition is the rank to count, e.g. 2 for second choice, -1 for last place
340	
341	    // initialize counts[candidateName] = 0 for each candidate
342	    let counts = {};
343	    candidates.forEach((c) => (counts[c.name] = 0));
344	
345	    ballots.forEach((ballot) => {
346	
347	      // ranked is an ordered array of candidates by their ranks
348	      let ranked = ballot.ranks
349	        .map((rank, i) => ({
350	          candidate: allCandidates[i],
351	          rank: rank,
352	        }))
353	        .filter((e) => !isNaN(e.rank))
354	        .sort((a, b) => a.rank - b.rank);
355	
356	      if (ranked.length > Math.abs(rankPosition) - 1) {
357	        let idx = rankPosition === -1 ? ranked.length - 1 : rankPosition - 1;
358	        let chosen = ranked[idx];
359	        if (chosen && counts.hasOwnProperty(chosen.candidate.name)) {
360	          counts[chosen.candidate.name]++;
361	        }
362	      }
363	    });
364	    logProcess3(
365	      "",
366	      "",
367	      `By rank ${rankPosition === -1 ? "Last" : rankPosition}: ` +
368	        Object.entries(counts)
369	          .map(([k, v]) => `${k}: ${v}`)
370	          .join(", ")
371	    );
372	    return counts;
373	  }
374	
375	  let counts, targetValue, filterFn;
376	  if (mode === "leastSecond") {
377	    counts = countByRank(2);
378	    // now set filter to look for the lowest count and return those candidates
379	    targetValue = Math.min(...Object.values(counts));
380	    filterFn = (c) => counts[c.name] === targetValue;
381	  } else if (mode === "mostLastPlace") {
382	    counts = countByRank(-1);
383	    targetValue = Math.max(...Object.values(counts));
384	    filterFn = (c) => counts[c.name] === targetValue;
385	  } else {
386	    return candidates; // No tie-breaker applied, return all candidates
387	  }
388	  return candidates.filter(filterFn);
389	}
390	
391	/**
392	 * Appends a row to the processing sheet for logging purposes.
393	 * @param {Array} rowArr - Array of values to log as a row.
394	 */
395	function logProcess(rowArr) {
396	  if (processingSheet) {
397	    processingSheet.appendRow(rowArr);
398	  }
399	}
400	function logProcess3(a,b,message) {
401	  if (processingSheet) {
402	    processingSheet.appendRow([a, b, message]);
403	  }
404	}
405	
406	/**
407	 * @param {Array<{weight:number}>} ballots
408	 * @returns {number} sum of weights, treating a missing weight as 1.
409	 */
410	function _sumBallotWeights(ballots) {
411	  return ballots.reduce((sum, b) => sum + (b.weight || 1), 0);
412	}
413	
